const chapters = [];
if(/\/chapter\//.test(baseUrl)) {
  let doc = org.jsoup.Jsoup.parse(result);
  let elements = doc.select(".chapListBody a");
  elements.forEach(a => {
    let text = a.text().trim();
    let href = a.attr("href");
    chapters.push({text, href})
  })
} else {
  try {
    let trimRes = String(result).trim();
    if (trimRes.startsWith("<")) {
      // 返回HTML，直接跳出，不执行JSON解析
      throw "not json";
    }
    let json = JSON.parse(result);
    if (json.data && json.data.length > 0){
      json.data.forEach(ch => {
        chapters.push({
          text: ch.chaptername,
          href: ch.chapterurl
        })
      })
    }
  } catch (e) {
    // 这里去掉toast弹窗，不再弹出Unexpected token报错干扰
    // java.longToast(e.message)
  }
}

chapters

