@js:
(() => {
const nextpageList = java.getStringList("@@.dropDown li:not(.cur)@data-p");
const jsUrl = result.match(/src="(\/templates\/js\/[A-Za-z0-9]+\.js)"/)?.[1];
if(nextpageList.size() == 0 || !jsUrl) return [];

const host = java.toURL(baseUrl).origin;
const cryptHtml = java.ajax(host+jsUrl);
const key = cryptHtml.match(/new AESCrypt\('([A-Za-z0-9]{32})'\)/)?.[1];
const iv = cryptHtml.match(/CryptoJS\.enc\.Utf8\.parse\('(\d{16})'\)/)?.[1];
if(!key || !iv) return [];

const id = baseUrl.match(/chapter\/(.*?)\.html/)?.[1];
const nextpages = Array.from(nextpageList, (page) => {
  let postBody = java.createSymmetricCrypto('AES/CBC/PKCS5Padding', key, iv).encryptBase64(JSON.stringify({
    id: id,
    page: page
  }));
  return host + '/index.php?action=loadChapterPage,' + JSON.stringify({
	   "method": "POST",
	   "body": "data="+encodeURIComponent(postBody)
  })
});

return nextpages
})()

